              <div className={`w-3 h-3 rounded-full border border-[rgba(255,255,255,0.2)] ml-auto flex items-center justify-center ${act.status === 'success' ? 'text-[var(--color-accent-green)]' : 'text-[var(--color-accent-red)]'}`}>
