              <span className="text-[var(--color-text-secondary)] flex items-center gap-1.5">
                <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: stat.color }} />
                {stat.label}
              </span>
              <span className="font-medium text-[var(--color-text-primary)]">{stat.value}%</span>
            </div>
            <div className="w-full bg-[rgba(255,255,255,0.05)] h-1 rounded-full overflow-hidden">
              <div className="h-full rounded-full" style={{ width: `${stat.value}%`, backgroundColor: stat.color }} />
            </div>
          </div>
        ))}
      </div>

      <button className="text-xs text-[var(--color-primary-light)] mt-6 hover:underline block">View full report →</button>
    </GlassPanel>
  </div>
));


// ─── MAIN PAGE COMPONENT ─────────────────────────────────────────────────────

export default function DashboardPage() {
  const { user, isLoading } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (!isLoading && !user) {
      router.replace("/login");
    }
  }, [isLoading, user, router]);

  if (isLoading || !user) {
    return (
      <div className="h-screen flex items-center justify-center bg-[var(--color-background)]">
        <span className="spinner-ring" />
      </div>
    );
  }

  const displayName = user.first_name || user.username;

  return (
    <div className="p-8">
      {/* Header Greeting */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-3 tracking-tight">
          Good morning, <span className="text-gradient">{displayName}!</span> 👋
        </h1>
        <p className="text-[var(--color-text-secondary)] text-sm mb-4">
          Atlas AI is ready to help you build, deploy, and scale.
        </p>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-[var(--radius-sm)] border border-[rgba(34,197,94,0.3)] bg-[rgba(34,197,94,0.1)] text-[var(--color-accent-green)] text-[10px] font-semibold uppercase tracking-wider">
            <div className="w-1.5 h-1.5 rounded-full bg-[var(--color-accent-green)]" />
            Workspace: Atlas Backend
          </div>
          <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-[var(--radius-sm)] border border-[rgba(34,197,94,0.3)] bg-[rgba(34,197,94,0.1)] text-[var(--color-accent-green)] text-[10px] font-semibold uppercase tracking-wider">
            <div className="w-1.5 h-1.5 rounded-full bg-[var(--color-accent-green)]" />
            Environment: Production
          </div>
          <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-[var(--radius-sm)] border border-[rgba(124,58,237,0.3)] bg-[rgba(124,58,237,0.1)] text-[var(--color-primary-light)] text-[10px] font-semibold uppercase tracking-wider">
            ✦ AI Context: Ready
          </div>
        </div>
      </div>

      <AiCommandInput />
      <MetricsGrid />
      <InfoColumns />
    </div>
  );
}

"use client";

import React, { useEffect, useState, use } from "react";
import Link from "next/link";
import { useOrganizationMembers } from "@/features/organizations";
import { useOrganization } from "@/features/organizations";
import { MemberRole } from "@/lib/api";
import { useAuth } from "@/contexts/AuthContext";

export default function OrganizationMembersPage({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = use(params);
  const orgId = resolvedParams.id;

  const { user } = useAuth();
  const { data: orgData } = useOrganization(orgId);
  const { 
    data: membersData, loading, error, 
    fetchMembers, inviteMember, updateRole, removeMember, transferOwnership 
  } = useOrganizationMembers(orgId);

  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteRole, setInviteRole] = useState<MemberRole>("MEMBER");
  const [isInviting, setIsInviting] = useState(false);
  const [inviteError, setInviteError] = useState<string | null>(null);

  useEffect(() => {
    fetchMembers();
  }, [fetchMembers]);

  const isOwner = user?.id === orgData?.owner_id;
  const currentMember = membersData?.items.find(m => m.user_id === user?.id);
  const canManage = currentMember?.role === "OWNER" || currentMember?.role === "ADMIN";

  async function handleInvite(e: React.FormEvent) {
    e.preventDefault();
    if (!inviteEmail) return;
    setIsInviting(true);
    setInviteError(null);
    try {
      await inviteMember(inviteEmail, inviteRole);
      setInviteEmail("");
      setInviteRole("MEMBER");
    } catch (err: any) {
      setInviteError(err.message || "Failed to invite user");
    } finally {
      setIsInviting(false);
    }
  }

  async function handleUpdateRole(memberId: string, newRole: MemberRole) {
    try {
      await updateRole(memberId, newRole);
    } catch (err: any) {
      alert(err.message || "Failed to update role");
    }
  }

  async function handleRemove(memberId: string) {
    if (!confirm("Are you sure you want to remove this member?")) return;
    try {
      await removeMember(memberId);
    } catch (err: any) {
      alert(err.message || "Failed to remove member");
    }
  }

  async function handleTransferOwnership(targetUserId: string) {
    if (!confirm("Are you sure you want to transfer ownership to this user? You will become an ADMIN.")) return;
    try {
      await transferOwnership(targetUserId);
    } catch (err: any) {
      alert(err.message || "Failed to transfer ownership");
    }
  }

  if (loading && !membersData) {
    return <div style={{ display: "flex", justifyContent: "center", padding: "60px 0" }}><span className="spinner-ring" /></div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", paddingBottom: "40px" }}>
      <div style={{ marginBottom: "32px" }}>
        <Link href={`/organizations/${orgId}`} style={{ color: "var(--text-secondary)", textDecoration: "none", fontSize: "14px", display: "inline-block", marginBottom: "16px" }}>
          ← Back to Organization
        </Link>
        <h1 className="hero-title" style={{ fontSize: "28px", margin: 0 }}>Manage Members</h1>
        <p style={{ color: "var(--text-secondary)", marginTop: "8px" }}>
          {orgData?.name}
        </p>
      </div>

      {error && (
        <div className="alert alert-error" style={{ marginBottom: "24px" }}>
          {error}
        </div>
      )}

      {canManage && (
        <div className="profile-card" style={{ marginBottom: "32px" }}>
          <h2 className="profile-card-title">Invite New Member</h2>
          {inviteError && <div className="alert alert-error" style={{ marginBottom: "16px" }}>{inviteError}</div>}
          <form onSubmit={handleInvite} style={{ display: "flex", gap: "12px", alignItems: "flex-end", flexWrap: "wrap" }}>
            <div className="form-group" style={{ marginBottom: 0, flex: "1 1 200px" }}>
              <label className="form-label" htmlFor="invite-email">Email</label>
              <input
                id="invite-email"
                type="email"
                required
                className="form-input"
                placeholder="user@example.com"
                value={inviteEmail}
                onChange={(e) => setInviteEmail(e.target.value)}
              />
            </div>
            <div className="form-group" style={{ marginBottom: 0, width: "150px" }}>
              <label className="form-label" htmlFor="invite-role">Role</label>
              <select 
                id="invite-role" 
                className="form-input" 
                value={inviteRole} 
                onChange={(e) => setInviteRole(e.target.value as MemberRole)}
              >
                <option value="VIEWER">Viewer</option>
                <option value="MEMBER">Member</option>
                <option value="ADMIN">Admin</option>
              </select>
            </div>
            <button type="submit" className="btn-primary" disabled={isInviting}>
              {isInviting ? "Inviting..." : "Send Invite"}
            </button>
          </form>
        </div>
      )}

      <div className="profile-card" style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ padding: "20px 24px", borderBottom: "1px solid var(--border)", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <h2 className="profile-card-title" style={{ margin: 0, padding: 0, border: "none" }}>Team Members</h2>
          <span style={{ color: "var(--text-secondary)", fontSize: "14px" }}>{membersData?.total || 0} total</span>
        </div>

        <div style={{ display: "flex", flexDirection: "column" }}>
          {membersData?.items.map((member) => (
            <div key={member.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "16px 24px", borderBottom: "1px solid var(--border)" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
                <div className="avatar" style={{ width: "40px", height: "40px", fontSize: "16px" }}>
                  {member.user.first_name?.[0]?.toUpperCase() || member.user.username[0].toUpperCase()}
                </div>
                <div>
                  <div style={{ fontWeight: 500 }}>{member.user.first_name} {member.user.last_name}</div>
                  <div style={{ color: "var(--text-secondary)", fontSize: "14px" }}>{member.user.email}</div>
                  {member.status === "INVITED" && <span className="badge badge-blue" style={{ marginTop: "4px" }}>Pending Invite</span>}
                </div>
              </div>

              <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                {canManage && member.role !== "OWNER" && member.user_id !== user?.id ? (
                  <select 
                    className="form-input" 
                    style={{ width: "110px", padding: "6px 12px", height: "auto" }}
                    value={member.role}
                    onChange={(e) => handleUpdateRole(member.id, e.target.value as MemberRole)}
                  >
                    <option value="VIEWER">Viewer</option>
                    <option value="MEMBER">Member</option>
                    <option value="ADMIN">Admin</option>
                  </select>
                ) : (
                  <span className="code-pill">{member.role}</span>
                )}

                {isOwner && member.role === "ADMIN" && member.status === "ACTIVE" && (
                   <button className="btn-ghost" style={{ fontSize: "12px", padding: "4px 8px" }} onClick={() => handleTransferOwnership(member.user_id)}>
                     Make Owner
                   </button>
                )}

                {(canManage || member.user_id === user?.id) && member.role !== "OWNER" && (
                  <button className="btn-ghost" style={{ color: "var(--error)", padding: "6px 12px" }} onClick={() => handleRemove(member.id)}>
                    {member.user_id === user?.id ? "Leave" : "Remove"}
                  </button>
                )}
              </div>
            </div>
          ))}
          {membersData?.items.length === 0 && (
            <div style={{ padding: "32px", textAlign: "center", color: "var(--text-secondary)" }}>
              No members found.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client"

import React, { useEffect, useState, use } from "react"
import { Activity, RefreshCw } from "lucide-react"
import { GlassPanel } from "@/components/ui/GlassPanel"
import { Button } from "@/components/ui/Button"
import { knowledgeApi, IndexJob, KnowledgeSource } from "@/lib/api"
import { getAccessToken } from "@/lib/auth"

export default function KnowledgeJobsPage({ params }: { params: Promise<{ id: string; workspaceId: string }> }) {
  const resolvedParams = use(params)
  const [sources, setSources] = useState<KnowledgeSource[]>([])
  const [jobs, setJobs] = useState<IndexJob[]>([])
  const [isLoading, setIsLoading] = useState(true)

  const fetchData = async () => {
    const token = getAccessToken()
    if (!token) return
    try {
      // Fetch all sources first to get their IDs
      const sourceData = await knowledgeApi.listSources(resolvedParams.workspaceId)
      setSources(sourceData)

      // Fetch jobs for each source
      let allJobs: IndexJob[] = []
      for (const s of sourceData) {
        const sourceJobs = await knowledgeApi.listJobs(s.id)
        allJobs = [...allJobs, ...sourceJobs]
      }

      // Sort jobs by started_at descending
      allJobs.sort((a, b) => new Date(b.started_at || 0).getTime() - new Date(a.started_at || 0).getTime())
      setJobs(allJobs)
    } catch (err) {
      console.error(err)
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchData()
  }, [resolvedParams.workspaceId])

  const getStatusColor = (status: string) => {
    switch(status) {
      case "completed": return "text-[var(--color-accent-green)]"
      case "running": return "text-[var(--color-accent-blue)]"
      case "failed": return "text-[var(--color-accent-red)]"
      default: return "text-[var(--color-text-secondary)]"
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-lg font-bold">Indexing Jobs</h2>
        <Button variant="secondary" size="sm" onClick={fetchData} className="gap-2">
          <RefreshCw className="w-3.5 h-3.5" /> Refresh
        </Button>
      </div>

      <GlassPanel>
        {isLoading ? (
          <div className="p-8 text-center text-[var(--color-text-muted)]">Loading jobs...</div>
        ) : jobs.length === 0 ? (
          <div className="p-8 text-center text-[var(--color-text-muted)]">No indexing jobs found.</div>
        ) : (
          <div className="p-2">
            {jobs.map(job => {
              const source = sources.find(s => s.id === job.source_id)
              return (
                <div key={job.id} className="p-4 border-b border-[var(--color-border-subtle)] last:border-0 hover:bg-[rgba(255,255,255,0.02)] transition-colors">
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded bg-[rgba(255,255,255,0.05)] flex items-center justify-center">
                        <Activity className="w-4 h-4 text-[var(--color-primary-light)]" />
                      </div>
                      <div>
                        <p className="text-sm font-medium">{source?.name || 'Unknown Source'}</p>
                        <p className="text-[10px] text-[var(--color-text-muted)] font-mono">{job.id}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <span className={`text-xs font-semibold uppercase tracking-wider ${getStatusColor(job.status)}`}>
                        {job.status}
                      </span>
                      <p className="text-[10px] text-[var(--color-text-muted)] mt-1">
                        {new Date(job.started_at || '').toLocaleTimeString()}
                      </p>
                    </div>
                  </div>

                  {/* Progress Bar */}
                  <div className="w-full bg-[rgba(255,255,255,0.05)] h-1.5 rounded-full overflow-hidden">
                    <div 
                      className={`h-full rounded-full transition-all duration-500 ${job.status === 'failed' ? 'bg-[var(--color-accent-red)]' : 'bg-[var(--color-primary-base)]'}`} 
                      style={{ width: `${Math.max(job.progress * 100, 2)}%` }} 
                    />
                  </div>

                  {job.error_message && (
                    <p className="mt-2 text-xs text-[var(--color-accent-red)] bg-[rgba(239,68,68,0.1)] p-2 rounded">
                      {job.error_message}
                    </p>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </GlassPanel>
    </div>
  )
}

"use client"

import React, { useState, use } from "react"
import { useRouter } from "next/navigation"
import { GitBranch, CheckCircle2, AlertCircle } from "lucide-react"
import { GlassPanel } from "@/components/ui/GlassPanel"
import { Button } from "@/components/ui/Button"
import { Input } from "@/components/ui/Input"
import { Alert } from "@/components/ui/Alert"
import { FormField } from "@/components/ui/FormField"
import { knowledgeApi } from "@/lib/api"
import { getAccessToken } from "@/lib/auth"

export default function ConnectRepositoryPage({ params }: { params: Promise<{ id: string; workspaceId: string }> }) {
  const resolvedParams = use(params)
  const router = useRouter()

  const [provider, setProvider] = useState("github")
  const [repository, setRepository] = useState("")
  const [branch, setBranch] = useState("main")

  const [isConnecting, setIsConnecting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState(false)

  const handleConnect = async (e: React.FormEvent) => {
    e.preventDefault()
    const token = getAccessToken()
    if (!token || !repository.trim() || !branch.trim()) return

    setIsConnecting(true)
    setError(null)

    try {
      await knowledgeApi.connectRepository(
        token,
        resolvedParams.workspaceId,
        provider,
        repository,
        branch
      )
      setSuccess(true)
      setTimeout(() => {
        router.push(`/organizations/${resolvedParams.id}/workspaces/${resolvedParams.workspaceId}/knowledge/jobs`)
      }, 1500)
    } catch (err: any) {
      setError(err.detail || "Failed to connect repository")
    } finally {
      setIsConnecting(false)
    }
  }

  return (
    <div className="max-w-xl mx-auto space-y-6">
      <GlassPanel className="p-8">
        <div className="text-center mb-8">
          <div className="w-12 h-12 rounded-full bg-[rgba(255,255,255,0.05)] flex items-center justify-center mx-auto mb-4 border border-[rgba(255,255,255,0.1)]">
            <GitBranch className="w-6 h-6 text-[var(--color-text-primary)]" />
          </div>
          <h2 className="text-xl font-bold mb-2">Connect Repository</h2>
          <p className="text-sm text-[var(--color-text-secondary)]">
            Index your codebase so Atlas AI can write, refactor, and debug your code with full context.
          </p>
        </div>

        <form onSubmit={handleConnect} className="space-y-4">
          <FormField label="Provider">
            <select 
              value={provider}
              onChange={(e) => setProvider(e.target.value)}
              className="w-full h-10 bg-[rgba(0,0,0,0.2)] border border-[var(--color-border-subtle)] rounded-[var(--radius-sm)] px-3 text-sm focus:outline-none focus:border-[var(--color-primary-base)] transition-colors"
            >
              <option value="github">GitHub</option>
              <option value="gitlab" disabled>GitLab (Coming Soon)</option>
              <option value="azure" disabled>Azure DevOps (Coming Soon)</option>
            </select>
          </FormField>

          <FormField label="Repository Path" required>
            <Input 
              placeholder="e.g. facebook/react"
              value={repository}
              onChange={(e) => setRepository(e.target.value)}
              required
            />
          </FormField>

          <FormField label="Default Branch" required>
            <Input 
              placeholder="main"
              value={branch}
              onChange={(e) => setBranch(e.target.value)}
              required
            />
          </FormField>

          {error && (
            <Alert variant="error">
              {error}
            </Alert>
          )}

          {success && (
            <Alert variant="success">
              Repository connected! Starting index...
            </Alert>
          )}

          <div className="pt-4">
            <Button type="submit" variant="primary" className="w-full" disabled={isConnecting}>
              {isConnecting ? <span className="spinner-ring" /> : "Connect & Index"}
            </Button>
          </div>
        </form>
      </GlassPanel>
    </div>
  )
}

"use client"

import React, { useEffect, useState, use } from "react"
import { File, Trash2, RefreshCw } from "lucide-react"
import { GlassPanel } from "@/components/ui/GlassPanel"
import { Button } from "@/components/ui/Button"
import { knowledgeApi, KnowledgeSource } from "@/lib/api"
import { getAccessToken } from "@/lib/auth"

export default function KnowledgeSourcesPage({ params }: { params: Promise<{ id: string; workspaceId: string }> }) {
  const resolvedParams = use(params)
  const [sources, setSources] = useState<KnowledgeSource[]>([])
  const [isLoading, setIsLoading] = useState(true)

  const fetchSources = async () => {
    try {
      const data = await knowledgeApi.listSources(resolvedParams.workspaceId)
      setSources(data)
    } catch (err) {
      console.error(err)
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchSources()
  }, [resolvedParams.workspaceId])

  const handleDelete = async (sourceId: string) => {
    if (!confirm("Delete this source?")) return
    try {
      await knowledgeApi.deleteSource(sourceId)
      setSources(s => s.filter(x => x.id !== sourceId))
    } catch (err) {
      console.error(err)
    }
  }

  const getStatusColor = (status: string) => {
    switch(status) {
      case "ready": return "text-[var(--color-accent-green)] bg-[rgba(34,197,94,0.1)] border-[rgba(34,197,94,0.3)]"
      case "indexing": return "text-[var(--color-accent-blue)] bg-[rgba(59,130,246,0.1)] border-[rgba(59,130,246,0.3)]"
      case "failed": return "text-[var(--color-accent-red)] bg-[rgba(239,68,68,0.1)] border-[rgba(239,68,68,0.3)]"
      default: return "text-[var(--color-text-secondary)] bg-[rgba(255,255,255,0.05)] border-[rgba(255,255,255,0.1)]"
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-lg font-bold">Knowledge Sources</h2>
        <Button variant="secondary" size="sm" onClick={fetchSources} className="gap-2">
          <RefreshCw className="w-3.5 h-3.5" /> Refresh
        </Button>
      </div>

      <GlassPanel>
        {isLoading ? (
          <div className="p-8 text-center text-[var(--color-text-muted)]">Loading sources...</div>
        ) : sources.length === 0 ? (
          <div className="p-8 text-center text-[var(--color-text-muted)]">No sources uploaded yet.</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b border-[var(--color-border-subtle)] text-[11px] uppercase tracking-wider text-[var(--color-text-muted)]">
                  <th className="px-6 py-4 font-medium">Name</th>
                  <th className="px-6 py-4 font-medium">Type</th>
                  <th className="px-6 py-4 font-medium">Status</th>
                  <th className="px-6 py-4 font-medium">Date</th>
                  <th className="px-6 py-4 font-medium text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--color-border-subtle)]">
                {sources.map(source => (
                  <tr key={source.id} className="hover:bg-[rgba(255,255,255,0.02)] transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <File className="w-4 h-4 text-[var(--color-primary-light)]" />
                        <span className="text-sm font-medium">{source.name}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-[var(--color-text-secondary)] capitalize">
                      {source.source_type}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-0.5 rounded text-xs border font-medium uppercase tracking-wider ${getStatusColor(source.status)}`}>
                        {source.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-[var(--color-text-secondary)]">
                      {new Date(source.created_at).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <Button variant="ghost" size="icon" onClick={() => handleDelete(source.id)} className="text-[var(--color-accent-red)] hover:text-red-400">
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </GlassPanel>
    </div>
  )
}

"use client"

import React, { useState, useRef, use } from "react"
import { useRouter } from "next/navigation"
import { UploadCloud, File, CheckCircle2, AlertCircle } from "lucide-react"
import { GlassPanel } from "@/components/ui/GlassPanel"
import { Button } from "@/components/ui/Button"
import { knowledgeApi } from "@/lib/api"
import { getAccessToken } from "@/lib/auth"

export default function KnowledgeUploadPage({ params }: { params: Promise<{ id: string; workspaceId: string }> }) {
  const resolvedParams = use(params)
  const router = useRouter()
  const fileInputRef = useRef<HTMLInputElement>(null)

  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const [isUploading, setIsUploading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState(false)

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setSelectedFile(e.target.files[0])
      setError(null)
      setSuccess(false)
    }
  }

  const handleUpload = async () => {
    if (!selectedFile) return
    setIsUploading(true)
    setError(null)

    try {
      await knowledgeApi.upload(resolvedParams.workspaceId, selectedFile)
      setSuccess(true)
      setSelectedFile(null)
      setTimeout(() => {
        router.push(`/organizations/${resolvedParams.id}/workspaces/${resolvedParams.workspaceId}/knowledge/sources`)
      }, 1500)
    } catch (err: any) {
      setError(err.detail || "Failed to upload file")
    } finally {
      setIsUploading(false)
    }
  }

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <GlassPanel className="p-8">
        <h2 className="text-lg font-bold mb-6">Upload Knowledge Source</h2>

        {/* Upload Zone */}
        <div 
          className="border-2 border-dashed border-[var(--color-border-subtle)] rounded-[var(--radius-lg)] p-12 text-center hover:border-[var(--color-primary-base)] hover:bg-[rgba(124,58,237,0.05)] transition-colors cursor-pointer group"
          onClick={() => fileInputRef.current?.click()}
        >
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect} 
            className="hidden" 
          />
          <div className="w-12 h-12 rounded-full bg-[rgba(255,255,255,0.05)] flex items-center justify-center mx-auto mb-4 group-hover:bg-[rgba(124,58,237,0.1)] transition-colors">
            <UploadCloud className="w-6 h-6 text-[var(--color-text-secondary)] group-hover:text-[var(--color-primary-light)] transition-colors" />
          </div>
          <p className="text-sm font-medium mb-1">Click to browse or drag & drop</p>
          <p className="text-xs text-[var(--color-text-muted)]">
            PDF, Markdown, TXT, CSV, Code files (max 50MB)
          </p>
        </div>

        {/* Selected File */}
        {selectedFile && (
          <div className="mt-6 p-4 rounded-[var(--radius-md)] bg-[rgba(0,0,0,0.2)] border border-[var(--color-border-subtle)] flex items-center justify-between">
            <div className="flex items-center gap-3">
              <File className="w-5 h-5 text-[var(--color-primary-light)]" />
              <div>
                <p className="text-sm font-medium">{selectedFile.name}</p>
                <p className="text-xs text-[var(--color-text-muted)]">{(selectedFile.size / 1024 / 1024).toFixed(2)} MB</p>
              </div>
            </div>
            <div className="flex gap-2">
              <Button variant="ghost" size="sm" onClick={() => setSelectedFile(null)} disabled={isUploading}>
                Cancel
              </Button>
              <Button variant="primary" size="sm" onClick={handleUpload} disabled={isUploading}>
                {isUploading ? <span className="spinner-ring" /> : "Upload to Atlas"}
              </Button>
            </div>
          </div>
        )}

        {/* Feedback */}
        {error && (
          <div className="mt-4 p-3 bg-[rgba(239,68,68,0.1)] border border-[rgba(239,68,68,0.3)] rounded-[var(--radius-sm)] flex items-center gap-2 text-[var(--color-accent-red)] text-sm">
            <AlertCircle className="w-4 h-4" /> {error}
          </div>
        )}
        {success && (
          <div className="mt-4 p-3 bg-[rgba(34,197,94,0.1)] border border-[rgba(34,197,94,0.3)] rounded-[var(--radius-sm)] flex items-center gap-2 text-[var(--color-accent-green)] text-sm">
