        { name: "Search", icon: Search, href: base ? `${base}/knowledge` : "/search" },
      ]
    },
    {
      title: "AI & AUTOMATION",
      items: [
        { name: "Agents", icon: Bot, href: "/agents" },
        { name: "Deployments", icon: Rocket, href: "/deployments" },
      ]
