"use client";

import React, { createContext, useContext, useEffect, useState } from "react";
import { useOrganizations } from "@/features/organizations";
import { OrganizationRead } from "@/features/organizations/types";

interface OrganizationContextValue {
  activeOrganization: OrganizationRead | null;
  setActiveOrganizationId: (id: string) => void;
  isLoading: boolean;
  error: string | null;
}

const OrganizationContext = createContext<OrganizationContextValue | null>(null);

export function OrganizationProvider({ children }: { children: React.ReactNode }) {
  const { data, isLoading, error } = useOrganizations("mine");
  const [activeOrgId, setActiveOrgId] = useState<string | null>(null);

  useEffect(() => {
    // If no active org is set, but we loaded some, pick the first one
    if (!activeOrgId && data?.items && data.items.length > 0) {
      const saved = localStorage.getItem("atlas_active_org");
      if (saved && data.items.find((org) => org.id === saved)) {
        setActiveOrgId(saved);
      } else {
        setActiveOrgId(data.items[0].id);
      }
    }
  }, [data, activeOrgId]);

  const handleSetOrg = (id: string) => {
    setActiveOrgId(id);
    localStorage.setItem("atlas_active_org", id);
  };

  const activeOrganization = data?.items.find((org) => org.id === activeOrgId) || null;

  return (
    <OrganizationContext.Provider
      value={{
        activeOrganization,
        setActiveOrganizationId: handleSetOrg,
        isLoading,
        error,
      }}
    >
      {children}
    </OrganizationContext.Provider>
  );
}

export function useActiveOrganization() {
  const ctx = useContext(OrganizationContext);
  if (!ctx) {
    throw new Error("useActiveOrganization must be used within an OrganizationProvider");
  }
  return ctx;
}

import { request } from "@/lib/api";

export interface AIProvider {
  category: string;
  name: string;
  is_active: boolean;
  health_status: string;
  health_message: string;
}

export interface ChatResponse {
  response: string;
  context_used: boolean;
  model: string;
  chunks: string[];
}

export const aiApi = {
  getHealth: async (): Promise<any> => {
    return request<any>('/ai/health');
  },

  getProviders: async (): Promise<{ providers: AIProvider[] }> => {
    return request<{ providers: AIProvider[] }>('/ai/providers');
  },

  chat: async (prompt: string, workspaceId?: string): Promise<ChatResponse> => {
    return request<ChatResponse>('/ai/chat', {
      method: "POST",
      body: JSON.stringify({ prompt, workspace_id: workspaceId }),
    });
  },
};

import { useState } from "react";
import { request } from "@/lib/api";

export function useAgents(workspaceId: string) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const executeAgent = async (prompt: string, organizationId?: string) => {
    setLoading(true);
    setError(null);
    try {
      const response = await request<any>('/ai/agents/execute', {
        method: 'POST',
        body: JSON.stringify({
          prompt,
          workspace_id: workspaceId,
          organization_id: organizationId
        })
      });
      return response;
    } catch (err: any) {
      setError(err.message || "Failed to execute agent");
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const getStatus = async (executionId: string) => {
    try {
      const response = await request<any>(`/ai/agents/status/${executionId}`);
      return response;
    } catch (err: any) {
      throw err;
    }
  };

  return {
    executeAgent,
    getStatus,
    loading,
    error,
    clearError: () => setError(null)
  };
}

