/**
 * src/lib/api.ts
 *
 * ATLAS-009 — Typed API client for the Atlas backend.
 * All requests go through /api/* which Next.js rewrites to http://localhost:8000/*.
 */

const BASE_URL = process.env.NEXT_PUBLIC_API_URL ?? "/api";

export interface UserRead {
  id: string;
  email: string;
  username: string;
  first_name: string | null;
  last_name: string | null;
  avatar_url: string | null;
  is_active: boolean;
  is_verified: boolean;
  created_at: string;
  updated_at: string;
}

export interface TokenResponse {
  access_token: string;
  refresh_token: string;
  token_type: string;
}

export interface RegisterPayload {
  email: string;
  username: string;
  password: string;
  first_name?: string;
  last_name?: string;
}

export interface LoginPayload {
  email: string;
  password: string;
}

export class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly detail: string,
  ) {
    super(detail);
    this.name = "ApiError";
  }
}

export async function request<T>(
  path: string,
  options: RequestInit = {},
): Promise<T> {
  const url = `${BASE_URL}${path}`;

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
  };

  // Only run client-side where localStorage is available
  if (typeof window !== "undefined") {
    const { getAccessToken } = await import("@/lib/auth");
    const token = getAccessToken();
    if (token) {
      headers["Authorization"] = `Bearer ${token}`;
    }
  }

  // Support FormData which overrides Content-Type automatically if we delete it
  if (options.body instanceof FormData) {
    delete headers["Content-Type"];
  }

  const res = await fetch(url, {
    ...options,
    headers: {
      ...headers,
      ...(options.headers ?? {}), // Allow explicit overrides
    },
  });

  if (!res.ok) {
    let detail = `HTTP ${res.status}`;
    try {
      const body = await res.json();
      detail = body?.detail ?? detail;
    } catch {
      /* ignore parse error */
    }
    throw new ApiError(res.status, detail);
  }

  // 204 No Content
  if (res.status === 204) return undefined as unknown as T;
  return res.json() as Promise<T>;
}

export function withAuth(token: string): HeadersInit {
  // Deprecated: No longer needed. request<T> auto-attaches tokens.
  return {};
}

export const api = {
  register(payload: RegisterPayload): Promise<UserRead> {
    return request<UserRead>("/auth/register", {
      method: "POST",
      body: JSON.stringify(payload),
    });
  },

  login(payload: LoginPayload): Promise<TokenResponse> {
    return request<TokenResponse>("/auth/login", {
      method: "POST",
      body: JSON.stringify(payload),
    });
  },

  me(): Promise<UserRead> {
    return request<UserRead>("/auth/me");
  },
};

